343	interface ParsedOptions {
344	  devices: string[];
345	  from?: number;
346	  to?: number;
347	  tz?: string;
348	  maxInterval?: number;
349	}
350	
351	/** 解析最大采样间隔限制(正整数秒数);无效返回 null。 */
352	function parseMaxInterval(raw: string): number | null {
353	  const v = raw.trim();
354	  if (!/^\d+$/.test(v)) return null;
355	  const n = Number(v);
356	  if (!Number.isSafeInteger(n) || n < 1) return null;
357	  return n;
358	}
359	
360	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
361	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
362	  const devices: string[] = [];
363	  let from: number | undefined;
364	  let to: number | undefined;
365	  let tz: string | undefined;
366	  let maxInterval: number | undefined;
367	  for (let i = 0; i < rest.length; i++) {
368	    let opt = rest[i];
369	    let value: string | undefined;
370	    const eq = opt.indexOf('=');
371	    if (opt.startsWith('--') && eq !== -1) {
372	      value = opt.slice(eq + 1);
373	      opt = opt.slice(0, eq);
374	    } else if (opt.startsWith('--')) {
375	      value = rest[i + 1];
376	      if (value === undefined) return `选项 '${opt}' 缺少值`;
377	      i++;
378	    } else {
379	      return `无法识别的参数 '${opt}'`;
380	    }
381	    if (opt === '--device') {
382	      if (value.trim() === '') return "'--device' 的值不能为空";
383	      devices.push(value);
384	    } else if (opt === '--from' || opt === '--to') {
385	      const ts = parseIso8601(value.trim());
386	      if (ts === null) {
387	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
388	      }
389	      if (opt === '--from') from = ts;
390	      else to = ts;
391	    } else if (opt === '--tz' && allowTz) {
392	      tz = value.trim();
393	      if (tz === '') return "'--tz' 的值不能为空";
394	    } else if (opt === '--max-interval' && allowMaxInterval) {
395	      const n = parseMaxInterval(value);
396	      if (n === null) {
397	        return `选项 '--max-interval' 的值无效: '${value.trim()}'(需正整数秒数)`;
398	      }
399	      maxInterval = n;
400	    } else {
401	      return `无法识别的选项 '${opt}'`;
402	    }
403	  }
404	  return { devices, from, to, tz, maxInterval };
405	}
406	
407	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
408	function checkTz(tz: string): string | null {
409	  if (loadTimezone(tz) === null) {
410	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
411	  }
412	  return null;
413	}
414	
415	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
416	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
417	  const out = new Map<string, string[]>();
418	  for (let i = 0; i < rest.length; i++) {
419	    let opt = rest[i];
420	    let value: string | undefined;
421	    const eq = opt.indexOf('=');
422	    if (opt.startsWith('--') && eq !== -1) {
423	      value = opt.slice(eq + 1);
424	      opt = opt.slice(0, eq);
425	    } else if (opt.startsWith('--')) {
426	      value = rest[i + 1];
427	      if (value === undefined) return `选项 '${opt}' 缺少值`;
428	      i++;
429	    } else {
430	      return `无法识别的参数 '${opt}'`;
431	    }
432	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
433	    const list = out.get(opt);
434	    if (list) list.push(value);
435	    else out.set(opt, [value]);
436	  }
437	  return out;
438	}
439	
440	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
441	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
442	  const list = flags.get(name);
443	  if (!list || list.length !== 1) return null;
444	  return list[0];
445	}
446	
447	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
448	function dateFlag(value: string, label: string): { date: string } | string {
449	  const v = value.trim();
450	  if (parseUtcDate(v) === null) {
451	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
452	  }
453	  return { date: v };
454	}
