456	function cmdRule(rest: string[]): number {
457	  const [sub, ...subrest] = rest;
458	  if (sub === 'list') {
459	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
460	    return cmdRuleList();
461	  }
462	  if (sub === 'create') {
463	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold', '--tz', '--max-interval', '--schedule']);
464	    if (typeof flags === 'string') return usageError(flags);
465	    const idRaw = oneFlag(flags, '--id');
466	    const deviceList = flags.get('--device');
467	    const groupList = flags.get('--group');
468	    const thresholdRaw = oneFlag(flags, '--threshold');
469	    const tzList = flags.get('--tz');
470	    const maxIntervalList = flags.get('--max-interval');
471	    const scheduleList = flags.get('--schedule');
472	    if (idRaw === null || thresholdRaw === null) {
473	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
474	    }
475	    if (tzList !== undefined && tzList.length !== 1) {
476	      return usageError("'rule create' 的 --tz 只能出现一次");
477	    }
478	    if (maxIntervalList !== undefined && maxIntervalList.length !== 1) {
479	      return usageError("'rule create' 的 --max-interval 只能出现一次");
480	    }
481	    if (scheduleList !== undefined && scheduleList.length !== 1) {
482	      return usageError("'rule create' 的 --schedule 只能出现一次");
483	    }
484	    const hasDevice = deviceList !== undefined;
485	    const hasGroup = groupList !== undefined;
486	    if (hasDevice === hasGroup) {
487	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
488	    }
489	    if ((deviceList !== undefined && deviceList.length !== 1) ||
490	      (groupList !== undefined && groupList.length !== 1)) {
491	      return usageError("'rule create' 的目标选项只能出现一次");
492	    }
493	    const id = idRaw.trim();
494	    if (id === '') return usageError('规则标识不能为空');
495	    const thresholdMilli = parseKwh(thresholdRaw.trim());
