748	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
749	  const segments: string[][] = [[]];
750	  for (const tok of rest) {
751	    if (tok === '--item') segments.push([]);
752	    else segments[segments.length - 1].push(tok);
753	  }
754	  const headFlags = parseFlags(segments[0], ['--request']);
755	  if (typeof headFlags === 'string') return headFlags;
756	  const requestRaw = oneFlag(headFlags, '--request');
757	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
758	  const requestId = requestRaw.trim();
759	  if (requestId === '') return '请求标识不能为空';
760	  const itemSegs = segments.slice(1);
761	  if (itemSegs.length === 0) {
762	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
763	  }
764	  const items: CorrectionItem[] = [];
765	  for (const seg of itemSegs) {
766	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
767	    if (typeof flags === 'string') return flags;
768	    const deviceRaw = oneFlag(flags, '--device');
769	    const atRaw = oneFlag(flags, '--at');
770	    const expectRaw = oneFlag(flags, '--expect');
771	    const setRaw = oneFlag(flags, '--set');
772	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
773	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
774	    }
775	    const device = deviceRaw.trim();
776	    if (device === '') return "'--device' 的值不能为空";
777	    const ts = parseIso8601(atRaw.trim());
778	    if (ts === null) {
779	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
780	    }
781	    const expectedMilli = parseKwh(expectRaw.trim());
782	    if (expectedMilli === null) {
783	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
784	    }
785	    const replacementMilli = parseKwh(setRaw.trim());
786	    if (replacementMilli === null) {
787	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
788	    }
789	    items.push({ device, ts, expectedMilli, replacementMilli });
