817	  // 旧 restore 事务——那正是救援要留存并放弃的对象;恢复日志损坏不再阻塞
818	  // 救援入口。其余所有入口(含无参数、--help/-h、非法参数)都先完成启动
819	  // 自恢复协调,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
820	  const [cmd, ...rest] = args;
821	  if (cmd === 'rescue') {
822	    const result = withRescueCoordination<number>(() => {
823	      if (rest.length !== 1) {
