825	      }
826	      return cmdRescue(rest[0]);
827	    });
828	    return typeof result === 'number' ? result : 1;
829	  }
830	  const result = withDirectoryCoordination<number>(() => runCommand(args));
831	  return typeof result === 'number' ? result : 1;
