859	  if (cmd === 'daily') {
860	    const parsed = parseOptions(rest, true, true);
861	    if (typeof parsed === 'string') return usageError(parsed);
862	    if (parsed.from === undefined || parsed.to === undefined) {
863	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
864	    }
865	    if (parsed.from >= parsed.to) {
866	      return usageError('查询起点必须早于终点(--from < --to)');
867	    }
868	    if (parsed.tz !== undefined) {
869	      const bad = checkTz(parsed.tz);
870	      if (bad !== null) return usageError(bad);
