881	  if (cmd === 'rule') return cmdRule(rest);
882	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
883	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
884	  if (cmd === 'group') return cmdGroup(rest);
885	  if (cmd === 'correct') return cmdCorrectEntry(rest);
886	  if (cmd === 'undo') return cmdUndoEntry(rest);
887	
888	  if (cmd === 'corrections') {
889	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
890	    return cmdCorrections();
891	  }
892	
893	  if (cmd === 'ack') {
894	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
895	    const alertId = rest[0].trim();
896	    if (alertId === '') return usageError('告警标识不能为空');
897	    return cmdAck(alertId);
