1	// group schedule-report 子命令:按本地运行时间表(每周窗口 + 日期例外)把查询
2	// 范围划分为运行与非运行两类时段,分别核查分组能耗的只读报表,用于核查停运消耗。
3	//
4	// - 时间表为零个或多个每周窗口加零个或多个日期例外。每周窗口:开始星期 +
5	//   起止 HH:mm。开始限 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始
6	//   即跨至下一日(尾段沿用开始日规则,周日可跨至周一)。窗口起点含、终点不含,
7	//   重叠或重复取并集。日期例外以真实 YYYY-MM-DD 指定当天运行窗口(限当日
8	//   00:00-24:00,起点含、终点不含且起点必须更早,不跨夜)或明确全天停运(off);
9	//   同日期窗口取并集,重复或等价拆分不影响含义;全天停运与该日期窗口并存拒绝。
10	//   例外按当地日期匹配,替换该日全部运行集合(含上一日每周跨夜窗口的尾段),
11	//   仅作用于当天,其他日期仍用每周表。旧格式(仅每周窗口)仍可使用,也允许
12	//   只有例外;零个窗口且无例外(空表)表示全部非运行。
13	// - 分类按实际时刻的当地日期与墙钟:每秒只属一类;夏令时跳过时段不虚构
14	//   覆盖,回拨重复时段各自分类,不套固定偏移或日长。--tz 只解释时间表,
15	//   不重新解释起止时刻或已存读数。
16	// - 能耗口径与 group daily 相同:按当时生效成员与完整读数时序,全部成员
17	//   可信才累加消耗,任一成员下降优先为异常,否则任一成员未知为未知;首个
18	//   版本生效前、读数首末之外与孤立读数未知,不外推。采样限制按原始相邻
19	//   区间判断,裁切不使过长区间可信,等于限制仍可信;有效片段取原区间起点
20	//   累计比例向下取整的两端差,切分不重置起点;BigInt 精确计算,kWh 固定
21	//   三位小数。
22	// - 两类覆盖合计等于查询时长,消耗合计等于同范围、同限制的分组日报,拆开
23	//   查询相加一致;覆盖按时间计,不叠加成员秒数。
24	// - 只读:不改写时间表或业务存储,不自动评估;修正撤销后重查使用当前读数。
25	//   成功(含不可计算结果)返回 0;非法时间表返回 2;时间表文件不可读、未知
26	//   分组、所用存储损坏或全库重复读数身份返回 1,指出原因,不输出部分报表。
27	
28	import { readFileSync } from 'node:fs';
29	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
30	import { formatIsoUtc, parseUtcDate } from './time.ts';
31	import { loadTimezone, wallSegments } from './tz.ts';
32	import { formatKwh } from './value.ts';
33	import { formatGapLine, maxIntervalText, mergeGaps, type GapDetail } from './report.ts';
34	import {
35	  computeGroupSegment,
36	  loadCheckedSeriesByDevice,
37	  loadGroups,
38	  type Group,
39	} from './groups.ts';
40	
41	function err(message: string): void {
42	  console.error(`meterwatch: ${message}`);
43	}
44	
45	export interface ScheduleWindow {
46	  /** 开始星期,0=周日 .. 6=周六。 */
47	  startDow: number;
48	  /** 开始当日的起始分钟,0..1439。 */
49	  startMin: number;
50	  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
51	  endMin: number;
52	}
53	
54	export interface DayWindow {
55	  /** 当日起始分钟,0..1439。 */
56	  startMin: number;
57	  /** 当日结束分钟(不含),恒大于 startMin,最大 1440(例外窗口不跨夜)。 */
58	  endMin: number;
59	}
60	
61	export interface ScheduleException {
62	  /** 当地日期,YYYY-MM-DD(真实日期)。 */
63	  date: string;
64	  /** 当天运行窗口(并集,限当日 00:00-24:00,起点含、终点不含);
65	   *  空数组表示明确全天停运(与没有例外不同)。 */
66	  windows: DayWindow[];
67	}
68	
69	export interface Schedule {
70	  /** 每周运行窗口。 */
71	  windows: ScheduleWindow[];
72	  /** 日期例外,日期唯一;按当地日期匹配并替换该日全部运行集合。 */
73	  exceptions: ScheduleException[];
74	}
75	
76	const DOW_BY_NAME: Record<string, number> = {
77	  sun: 0,
78	  mon: 1,
79	  tue: 2,
80	  wed: 3,
81	  thu: 4,
82	  fri: 5,
83	  sat: 6,
84	};
85	
86	/** 星期序号的显示名(0=周日 .. 6=周六)。 */
87	const DOW_NAMES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
88	
89	/** 一周分钟数(7 * 1440)。 */
90	const WEEK_MINUTES = 7 * 1440;
91	
92	/**
93	 * 单个窗口相对开始日的最大结束分钟(两天):分类只对每个当地日期回看
94	 * 上一日开始的窗口,故规范形窗口最长跨至下一日结束,更长的时间段必须
95	 * 拆成多个窗口表示。
96	 */
97	const MAX_WINDOW_END_MIN = 2 * 1440;
98	
99	/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
100	function parseHm(raw: string, allow24: boolean): number | null {
101	  const m = /^(\d{2}):(\d{2})$/.exec(raw);
102	  if (!m) return null;
103	  const h = Number(m[1]);
104	  const mi = Number(m[2]);
105	  if (mi > 59) return null;
106	  if (h > 23) {
107	    if (allow24 && h === 24 && mi === 0) return 1440;
108	    return null;
109	  }
110	  return h * 60 + mi;
111	}
112	
113	/**
114	 * 解析运行时间表文本(每周窗口 + 日期例外)。每行一条:
115	 *   <星期> <开始 HH:mm> <结束 HH:mm>          每周运行窗口
116	 *   <YYYY-MM-DD> <开始 HH:mm> <结束 HH:mm>    日期例外:当天运行窗口
117	 *   <YYYY-MM-DD> off                          日期例外:当天明确全天停运
118	 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写);每周窗口开始限
119	 * 00:00-23:59,结束另可 24:00,同值起止拒绝,结束早于开始跨至下一日。例外日期
120	 * 必须是真实日期;例外窗口限当日 00:00-24:00,起点含、终点不含且起点必须更早
121	 * (不跨夜);同日期窗口取并集,重复或等价拆分不影响含义;全天停运(off,
122	 * 不区分大小写)与该日期窗口并存拒绝。重叠或重复窗口不在此拒绝,分类时取并集。
123	 * 非法时返回错误消息字符串。
124	 */
125	export function parseSchedule(text: string): Schedule | string {
126	  const windows: ScheduleWindow[] = [];
127	  const excByDate = new Map<string, { off: boolean; windows: DayWindow[] }>();
128	  const lines = text.split(/\r\n|\r|\n/);
129	  for (let i = 0; i < lines.length; i++) {
130	    const hash = lines[i].indexOf('#');
131	    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
132	    if (line === '') continue;
133	    const where = `line ${i + 1}`;
134	    const parts = line.split(/\s+/);
135	    if (/^\d{4}-\d{2}-\d{2}$/.test(parts[0])) {
136	      // 日期例外行:真实 YYYY-MM-DD;'<date> off' 或 '<date> <开始> <结束>'。
137	      const date = parts[0];
138	      if (parseUtcDate(date) === null) {
139	        return `${where}: invalid date '${date}' (expect a real YYYY-MM-DD date)`;
140	      }
141	      const exc = excByDate.get(date);
142	      if (parts.length === 2 && parts[1].toLowerCase() === 'off') {
143	        if (exc !== undefined && exc.windows.length > 0) {
144	          return `${where}: date '${date}' has both 'off' (all-day shutdown) and running windows; keep only one`;
145	        }
146	        excByDate.set(date, { off: true, windows: [] });
147	        continue;
148	      }
149	      if (parts.length !== 3) {
150	        return `${where}: expect '<date> <start HH:mm> <end HH:mm>' or '<date> off'`;
151	      }
152	      const start = parseHm(parts[1], false);
153	      if (start === null) {
154	        return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
155	      }
156	      const end = parseHm(parts[2], true);
157	      if (end === null) {
158	        return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
159	      }
160	      // 例外窗口限当日 00:00-24:00,起点必须更早,不跨夜。
161	      if (end <= start) {
162	        return `${where}: exception window end must be later than start (same-day window within 00:00-24:00, no overnight)`;
163	      }
164	      if (exc !== undefined && exc.off) {
165	        return `${where}: date '${date}' has both 'off' (all-day shutdown) and running windows; keep only one`;
166	      }
167	      if (exc === undefined) excByDate.set(date, { off: false, windows: [{ startMin: start, endMin: end }] });
168	      else exc.windows.push({ startMin: start, endMin: end });
169	      continue;
170	    }
171	    if (parts.length !== 3) {
172	      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun), ` +
173	        `'<YYYY-MM-DD> <start HH:mm> <end HH:mm>' or '<YYYY-MM-DD> off'`;
174	    }
175	    // 只认对象自身的星期键,避免 constructor/__proto__/toString 等原型名被
176	    // 误当成合法星期(那些名字解析为 undefined,但用 in/点访问会命中原型)。
177	    const dow = Object.hasOwn(DOW_BY_NAME, parts[0].toLowerCase())
178	      ? DOW_BY_NAME[parts[0].toLowerCase() as keyof typeof DOW_BY_NAME]
179	      : undefined;
180	    if (dow === undefined) {
181	      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
182	    }
183	    const start = parseHm(parts[1], false);
184	    if (start === null) {
185	      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
186	    }
187	    const end = parseHm(parts[2], true);
188	    if (end === null) {
189	      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
190	    }
191	    if (end === start) {
192	      return `${where}: start and end must differ (both are '${parts[1]}')`;
193	    }
194	    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
195	    const endMin = end < start ? end + 1440 : end;
196	    windows.push({ startDow: dow, startMin: start, endMin });
197	  }
198	  const exceptions: ScheduleException[] = [...excByDate.entries()].map(([date, e]) => ({
199	    date,
200	    windows: e.windows,
201	  }));
202	  exceptions.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
203	  return { windows, exceptions };
204	}
205	
206	/**
207	 * 把每周运行窗口规范化为并集的最简形式:按周分钟(0..10079)展开为覆盖
208	 * 集合(结束越过周界的窗口取模回卷),再合并为按周分钟升序、互不重叠、
209	 * 互不相邻的窗口列表;超过两天的连续覆盖按每个窗口最多跨至下一日结束
210	 * 切分(分类只回看上一日开始的窗口)。窗口顺序、重复与等价拆分(如
211	 * mon 08:00-12:00 加 mon 12:00-18:00 对比 mon 08:00-18:00)不影响规范形,
212	 * 故规范形相同当且仅当每周运行窗口的并集相同。空表(零个窗口)的规范形
213	 * 为空数组。
214	 */
215	export function canonicalizeWindows(windows: ScheduleWindow[]): ScheduleWindow[] {
216	  const covered = new Uint8Array(WEEK_MINUTES);
217	  for (const w of windows) {
218	    const s = w.startDow * 1440 + w.startMin;
219	    const e = w.startDow * 1440 + w.endMin;
220	    for (let m = s; m < e; m++) covered[m % WEEK_MINUTES] = 1;
221	  }
222	  const out: ScheduleWindow[] = [];
223	  let m = 0;
224	  while (m < WEEK_MINUTES) {
225	    if (covered[m] === 0) {
226	      m++;
227	      continue;
228	    }
229	    const s = m;
230	    while (m < WEEK_MINUTES && covered[m] === 1) m++;
231	    // 连续覆盖段 [s, m):切成每个窗口最多跨至下一日结束(分类只回看一天)。
232	    let cur = s;
233	    while (cur < m) {
234	      const startDow = Math.floor(cur / 1440);
235	      const end = Math.min(m, startDow * 1440 + MAX_WINDOW_END_MIN);
236	      out.push({ startDow, startMin: cur - startDow * 1440, endMin: end - startDow * 1440 });
237	      cur = end;
238	    }
239	  }
240	  return out;
241	}
242	
243	/** 把同一天的例外窗口合并为并集最简形:按开始分钟升序、互不重叠、互不相邻。 */
244	function mergeDayWindows(windows: DayWindow[]): DayWindow[] {
245	  const sorted = [...windows].sort((a, b) => a.startMin - b.startMin || a.endMin - b.endMin);
246	  const out: DayWindow[] = [];
247	  for (const w of sorted) {
248	    const last = out[out.length - 1];
249	    if (last && w.startMin <= last.endMin) {
250	      if (w.endMin > last.endMin) last.endMin = w.endMin;
251	    } else {
252	      out.push({ startMin: w.startMin, endMin: w.endMin });
253	    }
254	  }
255	  return out;
256	}
257	
258	/**
259	 * 把日期例外规范化为最简形式:同日期窗口合并为并集(重复或等价拆分不影响
260	 * 规范形),例外按日期升序、日期唯一;全天停运为空窗口数组(与没有例外不同)。
261	 * 规范形相同当且仅当例外日期映射及各日窗口并集相同。
262	 */
263	export function canonicalizeExceptions(exceptions: ScheduleException[]): ScheduleException[] {
264	  const byDate = new Map<string, DayWindow[]>();
265	  for (const e of exceptions) {
266	    const list = byDate.get(e.date);
267	    if (list) list.push(...e.windows);
268	    else byDate.set(e.date, [...e.windows]);
269	  }
270	  const out: ScheduleException[] = [...byDate.entries()].map(([date, wins]) => ({
271	    date,
272	    windows: mergeDayWindows(wins),
273	  }));
274	  out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
275	  return out;
276	}
277	
278	/** HH:mm 显示(分钟数可超过 1439,用于每周跨夜窗口的相对结束)。 */
279	function hmText(min: number): string {
280	  return `${String(Math.floor(min / 60)).padStart(2, '0')}:${String(min % 60).padStart(2, '0')}`;
281	}
282	
283	/**
284	 * 单个例外的展示形式:`YYYY-MM-DD off`(全天停运)或
285	 * `YYYY-MM-DD HH:mm-HH:mm+HH:mm-HH:mm`(当天运行窗口并集)。
286	 */
287	export function formatException(e: ScheduleException): string {
288	  if (e.windows.length === 0) return `${e.date} off`;
289	  return `${e.date} ${e.windows.map((w) => `${hmText(w.startMin)}-${hmText(w.endMin)}`).join('+')}`;
290	}
291	
292	/**
293	 * 时间表的展示形式:每周窗口 `dow HH:mm-HH:mm` 列表(逗号分隔;结束可跨夜,
294	 * 小时可大于 24(相对开始日)),零个窗口显示为 `(no running windows)`;
295	 * 有日期例外时追加 `; exceptions: <例外列表>`(按日期升序)。
296	 */
297	export function formatSchedule(schedule: Schedule): string {
298	  const weekly =
299	    schedule.windows.length === 0
300	      ? '(no running windows)'
301	      : schedule.windows
302	          .map((w) => `${DOW_NAMES[w.startDow]} ${hmText(w.startMin)}-${hmText(w.endMin)}`)
303	          .join(', ');
304	  if (schedule.exceptions.length === 0) return weekly;
305	  return `${weekly}; exceptions: ${schedule.exceptions.map(formatException).join(', ')}`;
306	}
307	
308	/**
309	 * 解析存储中的时间表字段(窗口数组,元素为 {startDow, startMin, endMin}):
310	 * startDow 0..6,startMin 0..1439,endMin 大于 startMin 且不超过两天(规范
311	 * 形窗口最多跨至下一日结束,与分类的回看口径一致)。非法返回 null,由
312	 * 调用方按损坏数据处理。
313	 */
314	export function validateStoredSchedule(value: unknown): ScheduleWindow[] | null {
315	  if (!Array.isArray(value)) return null;
316	  const out: ScheduleWindow[] = [];
317	  for (const w of value) {
318	    if (w === null || typeof w !== 'object') return null;
319	    const o = w as Record<string, unknown>;
320	    if (
321	      !Number.isSafeInteger(o.startDow) ||
322	      (o.startDow as number) < 0 ||
323	      (o.startDow as number) > 6 ||
324	      !Number.isSafeInteger(o.startMin) ||
325	      (o.startMin as number) < 0 ||
326	      (o.startMin as number) > 1439 ||
327	      !Number.isSafeInteger(o.endMin) ||
328	      (o.endMin as number) <= (o.startMin as number) ||
329	      (o.endMin as number) > MAX_WINDOW_END_MIN
330	    ) {
331	      return null;
332	    }
333	    out.push({
334	      startDow: o.startDow as number,
335	      startMin: o.startMin as number,
336	      endMin: o.endMin as number,
337	    });
338	  }
339	  return out;
340	}
341	
342	/**
343	 * 解析存储中的日期例外字段(数组,元素为 {date, windows:[{startMin,endMin}]}):
344	 * date 为真实 YYYY-MM-DD 且唯一;窗口 startMin 0..1439,endMin 大于 startMin
345	 * 且不超过 1440(例外窗口限当日,不跨夜);空窗口数组表示明确全天停运。
346	 * 字段缺失(undefined)按无例外(旧规则/旧快照)返回空数组;存在但非法返回
347	 * null,由调用方按损坏数据处理。
348	 */
349	export function validateStoredExceptions(value: unknown): ScheduleException[] | null {
350	  if (value === undefined) return [];
351	  if (!Array.isArray(value)) return null;
352	  const seen = new Set<string>();
353	  const out: ScheduleException[] = [];
354	  for (const e of value) {
355	    if (e === null || typeof e !== 'object') return null;
356	    const o = e as Record<string, unknown>;
357	    if (typeof o.date !== 'string' || parseUtcDate(o.date) === null) return null;
358	    if (seen.has(o.date)) return null;
359	    seen.add(o.date);
360	    if (!Array.isArray(o.windows)) return null;
361	    const wins: DayWindow[] = [];
362	    for (const w of o.windows as unknown[]) {
363	      if (w === null || typeof w !== 'object') return null;
364	      const wo = w as Record<string, unknown>;
365	      if (
366	        !Number.isSafeInteger(wo.startMin) ||
367	        (wo.startMin as number) < 0 ||
368	        (wo.startMin as number) > 1439 ||
369	        !Number.isSafeInteger(wo.endMin) ||
370	        (wo.endMin as number) <= (wo.startMin as number) ||
371	        (wo.endMin as number) > 1440
372	      ) {
373	        return null;
374	      }
375	      wins.push({ startMin: wo.startMin as number, endMin: wo.endMin as number });
376	    }
377	    out.push({ date: o.date, windows: wins });
378	  }
379	  out.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0));
380	  return out;
381	}
382	
383	interface Period {
384	  /** 时段起点(含),epoch 秒。 */
385	  start: number;
386	  /** 时段终点(不含),epoch 秒。 */
387	  end: number;
388	}
389	
390	/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
391	function dowOfNaive(naiveMidnight: number): number {
392	  const days = Math.floor(naiveMidnight / 86400);
393	  return (((days + 4) % 7) + 7) % 7;
394	}
395	
396	/**
397	 * 把 [from, to) 按时间表(每周窗口 + 日期例外)分为运行与非运行两类实际 UTC
398	 * 时段,两类合计恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与
399	 * 墙钟:墙钟段切分自命名时区(段内偏移恒定、当地日期单一),窗口墙钟区间与段
400	 * 墙钟区间求交后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,回拨
401	 * 重复的墙钟两段实际时段各自分类,不套固定偏移或日长。日期例外按当地日期
402	 * 匹配,替换该日全部运行集合(含上一日每周跨夜窗口的尾段),仅作用于当天,
403	 * 其他日期仍用每周表(含上一日每周窗口跨至本日的尾段)。
404	 */
405	export function classifyPeriods(
406	  fmt: Intl.DateTimeFormat,
407	  from: number,
408	  to: number,
409	  schedule: Schedule,
410	): { running: Period[]; nonRunning: Period[] } {
411	  const raw: Period[] = [];
412	  const exceptionByDate = new Map(schedule.exceptions.map((e) => [e.date, e.windows]));
413	  if (schedule.windows.length > 0 || schedule.exceptions.length > 0) {
414	    // 各当地日期生效的窗口墙钟区间(按墙钟午夜缓存):有例外时为例外窗口
415	    // (替换每周表,含上一日每周跨夜窗口的尾段);否则为本日开始的每周窗口,
416	    // 以及上一日开始、跨至本日的每周窗口尾段。
417	    const wallByDate = new Map<string, Array<[number, number]>>();
418	    const wallIntervalsOf = (label: string): Array<[number, number]> => {
419	      const cached = wallByDate.get(label);
420	      if (cached) return cached;
421	      const dayNaive = parseUtcDate(label) as number;
422	      let wall: Array<[number, number]>;
423	      const exc = exceptionByDate.get(label);
424	      if (exc !== undefined) {
425	        wall = exc.map((w) => [dayNaive + w.startMin * 60, dayNaive + w.endMin * 60]);
426	      } else {
427	        wall = [];
428	        for (const w of schedule.windows) {
429	          for (const startNaive of [dayNaive, dayNaive - 86400]) {
430	            if (dowOfNaive(startNaive) !== w.startDow) continue;
431	            wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
432	          }
433	        }
434	      }
435	      wallByDate.set(label, wall);
436	      return wall;
437	    };
438	    for (const seg of wallSegments(fmt, from, to)) {
439	      const wall = wallIntervalsOf(seg.label);
440	      if (wall.length === 0) continue;
441	      // 段内偏移恒定,墙钟区间随 UTC 线性平移。
442	      const ws = seg.start + seg.offset;
443	      const we = seg.end + seg.offset;
444	      for (const [a, b] of wall) {
445	        const lo = Math.max(a, ws);
446	        const hi = Math.min(b, we);
447	        if (lo < hi) raw.push({ start: lo - seg.offset, end: hi - seg.offset });
448	      }
449	    }
450	    raw.sort((a, b) => a.start - b.start);
451	  }
452	  // 重叠或重复窗口取并集。
453	  const running: Period[] = [];
454	  for (const r of raw) {
455	    const last = running[running.length - 1];
456	    if (last && r.start <= last.end) {
457	      if (r.end > last.end) last.end = r.end;
458	    } else {
459	      running.push({ start: r.start, end: r.end });
460	    }
461	  }
462	  const nonRunning: Period[] = [];
463	  let cursor = from;
464	  for (const r of running) {
465	    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
466	    cursor = r.end;
467	  }
468	  if (cursor < to) nonRunning.push({ start: cursor, end: to });
469	  return { running, nonRunning };
470	}
471	
472	/**
473	 * 分组运行/非运行时段能耗报表:按本地运行时间表(每周窗口 + 日期例外)把
474	 * [from, to) 分为两类时段,分别按当时生效成员核查能耗。只读,不写入数据。
475	 * 返回进程退出码。
476	 */
477	export function cmdGroupScheduleReport(opts: {
478	  id: string;
479	  /** 本地运行时间表文件路径(只读)。 */
480	  schedulePath: string;
481	  from: number;
482	  to: number;
483	  /** 解释时间表的 IANA 时区;省略为 UTC。 */
484	  tz?: string;
485	  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
486	  maxInterval?: number;
487	}): number {
488	  const tzName = opts.tz ?? 'UTC';
489	  const tz = loadTimezone(tzName);
490	  if (!tz) {
491	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
492	    return 2;
493	  }
494	
495	  let text: string;
496	  try {
497	    text = readFileSync(opts.schedulePath, 'utf8');
498	  } catch (e) {
499	    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
500	    return 1;
501	  }
502	  const parsed = parseSchedule(text);
503	  if (typeof parsed === 'string') {
504	    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
505	    return 2;
506	  }
507	  const schedule = parsed;
508	
509	  let groups: Group[];
510	  try {
511	    groups = loadGroups(groupFilePath());
512	  } catch (e) {
513	    if (e instanceof StoreError) {
514	      err(e.message);
515	      return 1;
516	    }
517	    throw e;
518	  }
519	  const group = groups.find((g) => g.id === opts.id);
520	  if (!group) {
521	    err(`unknown group '${opts.id}'`);
522	    return 1;
523	  }
524	
525	  let seriesByDevice: Map<string, Reading[]>;
526	  try {
527	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
528	  } catch (e) {
529	    if (e instanceof StoreError) {
530	      err(e.message);
531	      return 1;
532	    }
533	    throw e;
534	  }
535	
536	  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, schedule);
537	
538	  console.log(`group: ${group.id}`);
539	  console.log(
540	    `schedule: ${opts.schedulePath} ` +
541	      `(${schedule.windows.length} weekly window(s), ${schedule.exceptions.length} exception(s))`,
542	  );
543	  console.log(`timezone: ${tzName}`);
544	  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);
545	
546	  const classes: Array<{ name: string; periods: Period[] }> = [
547	    { name: 'running', periods: running },
548	    { name: 'non-running', periods: nonRunning },
549	  ];
550	  let incomplete = false;
551	  const coverage: number[] = [];
552	  for (const c of classes) {
553	    let valid = 0;
554	    let anomaly = 0;
555	    let unknown = 0;
556	    let gapUnknown = 0;
557	    const gaps: GapDetail[] = [];
558	    let consumption = 0n;
559	    for (const p of c.periods) {
560	      const stats = computeGroupSegment(
561	        group.versions,
562	        seriesByDevice,
563	        p.start,
564	        p.end,
565	        opts.maxInterval,
566	      );
567	      valid += stats.valid;
568	      anomaly += stats.anomaly;
569	      unknown += stats.unknown;
570	      gapUnknown += stats.gapUnknown;
571	      mergeGaps(gaps, stats.gaps);
572	      consumption += stats.consumption;
573	    }
574	    let seconds = 0;
575	    for (const p of c.periods) seconds += p.end - p.start;
576	    coverage.push(seconds);
577	    const classIncomplete = anomaly > 0 || unknown > 0;
578	    if (classIncomplete) incomplete = true;
579	
580	    const consumptionText =
581	      valid > 0
582	        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
583	        : 'consumption=n/a (no valid coverage)';
584	    let line =
585	      `  class=${c.name}  ${consumptionText}` +
586	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
587	    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
588	    if (classIncomplete) line += '  INCOMPLETE';
589	    console.log(line);
590	    for (const p of c.periods) {
591	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
592	    }
593	    for (const g of gaps) {
594	      console.log(formatGapLine(g));
595	    }
596	  }
597	
598	  const status = incomplete
599	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
600	    : 'status=complete';
601	  console.log(
602	    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
603	      `  total=${opts.to - opts.from}s  ${status}`,
604	  );
605	  return 0;
606	}
607

