79	//   [02:00,02:30) x 仍在同一长区间 => 未知 1800(并集),gap 计 1800;y 下降后有效。
80	//   [02:30,24:00) 两成员 30 分钟密采样(相邻 1800s == 限制,仍可信)=> 有效 77400。
81	//   合计:有效 77400、异常 3600、未知 5400(=3600+1800),gap 并集 5400,总和 86400。
82	//   gap 明细(去重,三条):x 与 y 的 [前日23:00,01:00),以及 x 的 [01:00,02:30);
83	//   均指向原始相邻读数时刻,不被日界或 02:00 时点裁短。
84	const S2 = {
85	  valid: 77400,
86	  anomaly: 3600,
87	  unknown: 5400,
88	  gapUnion: 5400,
89	  rawGap1: '2026-01-12T23:00:00Z..2026-01-13T01:00:00Z',
90	  rawGap2: '2026-01-13T01:00:00Z..2026-01-13T02:30:00Z',
91	};
