114	// 时启用离线测试钩子,未设置时零行为。故障点见 src/backup.ts 的 testFaults()。
115	function runFault(dataDir, args, faults, cwd = dataDir) {
116	  const res = spawnSync(process.execPath, [APP, ...args], {
117	    encoding: 'utf8',
118	    cwd,
119	    env: { ...process.env, METERWATCH_DATA_DIR: dataDir, METERWATCH_TEST_FAULT: faults },
