177	function writeS1Materials(dir) {
178	  write(join(dir, 'r.csv'), [
179	    'device,time,reading',
180	    // m1:周一全天一个大区间,差值超安全整数且不能被时长整除。
181	    'm1,2026-01-05T00:00:00Z,9007199254740.000',
182	    'm1,2026-01-06T00:00:00Z,18014398509482.001',
183	    // m2:周一全天,运行窗内 12:02 起下降(下降优先于未知)。
184	    'm2,2026-01-05T00:00:00Z,0.000',
185	    'm2,2026-01-05T12:00:00Z,1.000',
186	    'm2,2026-01-05T12:02:00Z,2.000',
187	    'm2,2026-01-05T12:04:00Z,0.500',
188	    'm2,2026-01-06T00:00:00Z,2.500',
