202	function scenarioS1() {
203	  const S = 'S1 combined exact (big-int / non-divisible / second switch / window boundary)';
204	  const dir = makeDataDir();
205	  try {
206	    writeS1Materials(dir);
207	    let r = run(dir, ['import', 'r.csv']);
208	    check(S, r.code === 0, `import rc=${r.code} ${r.err}`);
209	    r = run(dir, ['group', 'configure', '--id', 'g1', '--at', '2026-01-01T00:00:00Z', '--device', 'm1', '--device', 'm2']);
210	    check(S, r.code === 0, `group v1 rc=${r.code} ${r.err}`);
211	    // 秒级成员切换:12:00:30 起 m3 加入(落在运行窗内,非运行部分成员不变)。
212	    r = run(dir, ['group', 'configure', '--id', 'g1', '--at', '2026-01-05T12:00:30Z', '--device', 'm1', '--device', 'm2', '--device', 'm3']);
213	    check(S, r.code === 0, `group v2 rc=${r.code} ${r.err}`);
214	
215	    // 等价拆分重试:同 id、同并集窗口 => 不新增,即使文件不同/顺序不同。
216	    r = run(dir, ['rule', 'create', '--id', 'nr', '--group', 'g1', '--threshold', EXPECTED.nrKwh, '--schedule', 'win.txt']);
