218	    r = run(dir, ['rule', 'create', '--id', 'nr', '--group', 'g1', '--threshold', EXPECTED.nrKwh, '--schedule', 'win-split.txt']);
219	    check(S, r.code === 0 && /already exists with identical parameters/.test(r.out) && /unchanged/.test(r.out),
220	      `equivalent split retry should be unchanged: rc=${r.code} out=${JSON.stringify(r.out)}`);

