7	// Number 安全整数范围,JSON 解析时已丢失精度,按损坏数据拒绝,不猜测原值。
8	
9	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
10	import { homedir } from 'node:os';
11	import { dirname, join } from 'node:path';
12	
13	export interface Reading {
