40	export interface UndoRecord {
41	  /** 撤销请求标识(已去除首尾空白,区分大小写),与修正请求共用唯一标识空间。 */
42	  requestId: string;
43	  /** 目标修正请求标识;只能是成功修正,不能是撤销请求。 */
