53	  /** 已成功提交的撤销记录,按成功发生顺序;与读数、修正历史同文件原子持久化。 */
54	  undos: UndoRecord[];
55	}
56	
57	export class StoreError extends Error {}
58	
59	/** 数据目录:环境变量 METERWATCH_DATA_DIR 指定,默认 ~/.meterwatch。 */
60	export function dataDirPath(): string {
61	  return process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
62	}
63	
64	export function dataFilePath(): string {
65	  return join(dataDirPath(), 'readings.json');
66	}
67	
68	/** 告警规则与历史的存储文件,与读数文件同目录、相互独立。 */
69	export function alertFilePath(): string {
70	  return join(dataDirPath(), 'alerts.json');
71	}
72	
73	/** 分组配置的存储文件,与读数、告警文件同目录、相互独立。 */
74	export function groupFilePath(): string {
75	  return join(dataDirPath(), 'groups.json');
76	}
77	
78	/**
79	 * 解析存储中的毫千瓦时字段:十进制数字字符串,或旧格式的安全整数数值。
80	 * 其他形式(含超出安全整数范围的数值,精度已丢失)返回 null,由调用方按损坏处理。
81	 */
82	export function parseStoredMilli(value: unknown): bigint | null {
83	  if (typeof value === 'string' && /^\d+$/.test(value)) return BigInt(value);
84	  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) {
85	    return BigInt(value);
86	  }
87	  return null;
88	}
89	
90	/**
91	 * 解析存储中的修正历史;字段缺失按空历史(旧版文件),存在但结构非法返回 null。
92	 */
93	function parseStoredCorrections(value: unknown): Correction[] | null {
94	  if (value === undefined) return [];
95	  if (!Array.isArray(value)) return null;
96	  const out: Correction[] = [];
97	  const ids = new Set<string>();
98	  for (const c of value as Array<Record<string, unknown>>) {
99	    if (
100	      c === null ||
101	      typeof c !== 'object' ||
102	      typeof c.requestId !== 'string' ||
103	      c.requestId.length === 0 ||
104	      !Array.isArray(c.items) ||
105	      c.items.length === 0 ||
106	      ids.has(c.requestId)
107	    ) {
108	      return null;
109	    }
110	    const items: CorrectionItem[] = [];
111	    for (const it of c.items as Array<Record<string, unknown>>) {
112	      const expectedMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.expectedMilli) : null;
113	      const replacementMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.replacementMilli) : null;
114	      const ok =
115	        it !== null &&
116	        typeof it === 'object' &&
117	        typeof it.device === 'string' &&
118	        it.device.length > 0 &&
119	        Number.isSafeInteger(it.ts) &&
120	        expectedMilli !== null &&
121	        replacementMilli !== null;
122	      if (!ok) return null;
123	      items.push({
124	        device: it.device as string,
125	        ts: it.ts as number,
126	        expectedMilli: expectedMilli as bigint,
127	        replacementMilli: replacementMilli as bigint,
128	      });
129	    }
130	    ids.add(c.requestId);
131	    out.push({ requestId: c.requestId, items });
132	  }
133	  return out;
134	}
135	
136	/**
137	 * 解析存储中的撤销历史;字段缺失按空历史(旧版文件,原修正视为未撤销),
138	 * 存在但结构非法或与修正历史不一致返回 null。
139	 */
140	function parseStoredUndos(value: unknown, corrections: Correction[]): UndoRecord[] | null {
141	  if (value === undefined) return [];
142	  if (!Array.isArray(value)) return null;
143	  const correctionIds = new Set(corrections.map((c) => c.requestId));
144	  const ids = new Set<string>();
145	  const targets = new Set<string>();
146	  const out: UndoRecord[] = [];
147	  for (const u of value as Array<Record<string, unknown>>) {
148	    const ok =
149	      u !== null &&
150	      typeof u === 'object' &&
151	      typeof u.requestId === 'string' &&
152	      u.requestId.length > 0 &&
153	      typeof u.targetId === 'string' &&
154	      u.targetId.length > 0 &&
155	      Number.isSafeInteger(u.restored) &&
156	      (u.restored as number) >= 0;
157	    if (!ok) return null;
158	    // 撤销与修正共用唯一标识空间;目标必须是已存修正且每个目标最多被撤销一次。
159	    if (ids.has(u.requestId as string) || correctionIds.has(u.requestId as string)) return null;
160	    if (!correctionIds.has(u.targetId as string) || targets.has(u.targetId as string)) return null;
161	    ids.add(u.requestId as string);
162	    targets.add(u.targetId as string);
163	    out.push({
164	      requestId: u.requestId as string,
165	      targetId: u.targetId as string,
166	      restored: u.restored as number,
167	    });
168	  }
169	  return out;
170	}
171	
172	/**
173	 * 解析读数存储的 JSON 结构(读数与修正、撤销历史)。
174	 * 结构非法抛出 StoreError;source 用于错误消息(如 `storage file <path>`)。
175	 */
176	export function parseStoreData(data: unknown, source: string): StoreData {
177	  const bad = (what: string): StoreError => new StoreError(`${source} is corrupted (${what})`);
178	  const readings = (data as { readings?: unknown })?.readings;
179	  if (!Array.isArray(readings)) throw bad('missing readings array');
180	  const out: Reading[] = [];
181	  for (const r of readings as Array<Record<string, unknown>>) {
182	    const milli = r !== null && typeof r === 'object' ? parseStoredMilli(r.milli) : null;
183	    const ok =
184	      r !== null &&
185	      typeof r === 'object' &&
186	      typeof r.device === 'string' &&
187	      r.device.length > 0 &&
188	      Number.isSafeInteger(r.ts) &&
189	      milli !== null;
190	    if (!ok) throw bad('invalid reading entry');
191	    out.push({ device: r.device as string, ts: r.ts as number, milli: milli as bigint });
192	  }
193	  const corrections = parseStoredCorrections((data as { corrections?: unknown })?.corrections);
194	  if (corrections === null) throw bad('invalid corrections');
195	  const undos = parseStoredUndos((data as { undos?: unknown })?.undos, corrections);
196	  if (undos === null) throw bad('invalid undos');
197	  return { readings: out, corrections, undos };
198	}
199	
200	/** 序列化为存储文件的 JSON 结构(毫千瓦时为十进制字符串,任意大数精确)。 */
201	export function serializeStoreData(data: StoreData): Record<string, unknown> {
202	  return {
203	    version: 1,
204	    readings: data.readings.map((r) => ({ device: r.device, ts: r.ts, milli: r.milli.toString() })),
205	    corrections: data.corrections.map((c) => ({
206	      requestId: c.requestId,
207	      items: c.items.map((it) => ({
208	        device: it.device,
209	        ts: it.ts,
210	        expectedMilli: it.expectedMilli.toString(),
211	        replacementMilli: it.replacementMilli.toString(),
212	      })),
213	    })),
214	    undos: data.undos.map((u) => ({
215	      requestId: u.requestId,
216	      targetId: u.targetId,
217	      restored: u.restored,
218	    })),
219	  };
220	}
221	
222	/** 读取存储(读数与修正历史);文件不存在返回空数据,存在但无法读取或内容损坏抛出 StoreError。 */
223	export function loadData(path: string): StoreData {
224	  let text: string;
225	  try {
226	    text = readFileSync(path, 'utf8');
227	  } catch (err) {
228	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return { readings: [], corrections: [], undos: [] };
229	    throw new StoreError(`cannot read storage file ${path}: ${(err as Error).message}`);
230	  }
231	  let data: unknown;
232	  try {
233	    data = JSON.parse(text);
234	  } catch {
235	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
236	  }
237	  return parseStoreData(data, `storage file ${path}`);
238	}
239	
240	/** 只取读数的便捷封装;语义与 loadData 相同。 */
241	export function loadStore(path: string): Reading[] {
242	  return loadData(path).readings;
243	}
244	
245	/** 原子写入存储(读数、修正历史与撤销记录同文件同时持久化);失败抛错,原有数据保持不变。 */
246	export function saveData(path: string, data: StoreData): void {
247	  mkdirSync(dirname(path), { recursive: true });
248	  const tmp = `${path}.tmp-${process.pid}`;
249	  const body = JSON.stringify(serializeStoreData(data), null, 2) + '\n';
250	  try {
251	    writeFileSync(tmp, body, 'utf8');
252	    renameSync(tmp, path);
253	  } catch (err) {
254	    throw new StoreError(`cannot write storage file ${path}: ${(err as Error).message}`);
255	  }
256	}
